function generateCommunityFlats() {
  const list = [];
  // Block A: 5 floors × 14 units (101-114, 201-214, 301-314, 401-414, 501-514) = 70 flats
  for (let floor = 1; floor <= 5; floor++) {
    for (let unit = 1; unit <= 14; unit++) {
      const num = `${floor}${String(unit).padStart(2, "0")}`;
      list.push({ id: `fl_A_${num}`, blockId: "A", flatNumber: num, residentName: "", active: true });
    }
  }
  // Block B: 5 floors × 14 units (101-114, 201-214, 301-314, 401-414, 501-514) = 70 flats
  for (let floor = 1; floor <= 5; floor++) {
    for (let unit = 1; unit <= 14; unit++) {
      const num = `${floor}${String(unit).padStart(2, "0")}`;
      list.push({ id: `fl_B_${num}`, blockId: "B", flatNumber: num, residentName: "", active: true });
    }
  }
  // Block C: 5 floors × 18 units (101-118, 201-218, 301-318, 401-418, 501-518) = 90 flats
  for (let floor = 1; floor <= 5; floor++) {
    for (let unit = 1; unit <= 18; unit++) {
      const num = `${floor}${String(unit).padStart(2, "0")}`;
      list.push({ id: `fl_C_${num}`, blockId: "C", flatNumber: num, residentName: "", active: true });
    }
  }
  return list;
}

