// ════════════════════════════════════════════════════════════════
// SANITIZATION & SAFE UTILITIES (XSS + CSV FORMULA INJECTION DEFENSE)
// ════════════════════════════════════════════════════════════════
function sanitizeHtml(str) {
  if (str === null || str === undefined) return "";
  return String(str)
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#039;");
}

function sanitizeCSVCell(val) {
  let str = String(val ?? "").trim();
  // Neutralize DDE / Formula injection in Excel/Sheets (=, +, -, @, tab, newline)
  if (/^[=+\-@\t\r]/.test(str)) {
    str = "'" + str;
  }
  return `"${str.replace(/"/g, '""')}"`;
}

const fmt = (n) => {
  const num = Number(n);
  if (isNaN(num) || !isFinite(num)) return "₹0";
  return "₹" + Math.round(num).toLocaleString("en-IN");
};

const fmtNum = (n) => {
  const num = Number(n);
  if (isNaN(num) || !isFinite(num)) return "0";
  return Math.round(num).toLocaleString("en-IN");
};

const parseAmount = (val) => {
  const num = Number(val);
  if (isNaN(num) || !isFinite(num) || num <= 0 || num > 10000000) return null;
  return Math.round(num);
};

// Timezone-safe local calendar date (YYYY-MM-DD)
const getLocalDateStr = (d = new Date()) => {
  const year = d.getFullYear();
  const month = String(d.getMonth() + 1).padStart(2, "0");
  const day = String(d.getDate()).padStart(2, "0");
  return `${year}-${month}-${day}`;
};

// Guaranteed exactly 7 days without timezone skew
const getFestivalDays = (festival) => {
  if (!festival || !festival.startDate) return [];
  const parts = festival.startDate.split("-").map(Number);
  if (parts.length !== 3 || parts.some(isNaN)) return [];
  const [y, m, d] = parts;
  return Array.from({ length: 7 }, (_, i) => {
    const date = new Date(y, m - 1, d + i);
    const mm = String(date.getMonth() + 1).padStart(2, "0");
    const dd = String(date.getDate()).padStart(2, "0");
    return `${date.getFullYear()}-${mm}-${dd}`;
  });
};

const calcEndDate = (startDateStr) => {
  if (!startDateStr) return "";
  const parts = startDateStr.split("-").map(Number);
  if (parts.length !== 3 || parts.some(isNaN)) return "";
  const [y, m, d] = parts;
  const end = new Date(y, m - 1, d + 6); // Exactly 7 days (day 1 to 7)
  const mm = String(end.getMonth() + 1).padStart(2, "0");
  const dd = String(end.getDate()).padStart(2, "0");
  return `${end.getFullYear()}-${mm}-${dd}`;
};

// ════════════════════════════════════════════════════════════════
// CSV EXPORT ENGINE
// ════════════════════════════════════════════════════════════════
function downloadCSV(filename, rows) {
  const csv = rows.map((r) => r.map(sanitizeCSVCell).join(",")).join("\n");
  const blob = new Blob(["\uFEFF" + csv], { type: "text/csv;charset=utf-8;" });
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  const safeName = filename.replace(/[^a-zA-Z0-9_\-\.]/g, "_");
  a.href = url;
  a.download = safeName;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  URL.revokeObjectURL(url);
}

