const BarChart = ({ data, color = "#f59e0b" }) => {
  if (!data || data.length === 0) return <div style={{ textAlign: "center", color: "#94a3b8", padding: 16, fontSize: 13 }}>No data</div>;
  const max = Math.max(...data.map((d) => d.value), 1);
  return (
    <div style={{ display: "flex", alignItems: "flex-end", gap: 10, height: 130, padding: "10px 0" }}>
      {data.map((d, i) => {
        const heightPct = Math.min(Math.max((d.value / max) * 90, 0), 90);
        return (
          <div key={i} style={{ flex: 1, display: "flex", flexDirection: "column", alignItems: "center", gap: 4 }}>
            <span style={{ fontSize: 10, color: "#64748b", fontWeight: 700 }}>{fmt(d.value)}</span>
            <div
              style={{
                width: "100%",
                background: color,
                borderRadius: "4px 4px 0 0",
                height: `${heightPct}px`,
                minHeight: d.value > 0 ? 6 : 0,
                transition: "height 0.4s ease",
              }}
            />
            <span style={{ fontSize: 11, color: "#334155", fontWeight: 700 }}>{d.label}</span>
          </div>
        );
      })}
    </div>
  );
};

const DonutChart = ({ data }) => {
  const total = data.reduce((s, d) => s + (d.value || 0), 0);
  const COLORS = ["#f59e0b", "#ef4444", "#8b5cf6", "#06b6d4", "#10b981", "#f97316", "#ec4899", "#6366f1", "#14b8a6"];
  let cumulative = 0;
  const r = 58, cx = 80, cy = 80, sw = 22;
  const circ = 2 * Math.PI * r;
  if (total <= 0) return <div style={{ textAlign: "center", color: "#94a3b8", padding: 24, fontSize: 13 }}>No expenses recorded yet</div>;

  return (
    <div style={{ display: "flex", gap: 16, alignItems: "center", flexWrap: "wrap" }}>
      <svg width={160} height={160} viewBox="0 0 160 160">
        {data.map((d, i) => {
          if (d.value <= 0) return null;
          const pct = d.value / total;
          const offset = circ * (1 - cumulative);
          const dashArr = `${circ * pct} ${circ * (1 - pct)}`;
          cumulative += pct;
          return (
            <circle
              key={i}
              cx={cx}
              cy={cy}
              r={r}
              fill="none"
              stroke={COLORS[i % COLORS.length]}
              strokeWidth={sw}
              strokeDasharray={dashArr}
              strokeDashoffset={offset}
              transform={`rotate(-90 ${cx} ${cy})`}
              style={{ transition: "all 0.5s" }}
            />
          );
        })}
        <text x={cx} y={cy - 4} textAnchor="middle" fontSize={13} fill="#0f172a" fontWeight={800}>{fmt(total)}</text>
        <text x={cx} y={cy + 14} textAnchor="middle" fontSize={10} fill="#64748b">Total Spent</text>
      </svg>
      <div style={{ display: "flex", flexDirection: "column", gap: 6, flex: 1, minWidth: 130 }}>
        {data.slice(0, 5).map((d, i) => (
          <div key={i} style={{ display: "flex", alignItems: "center", gap: 8 }}>
            <div style={{ width: 10, height: 10, borderRadius: 2, background: COLORS[i % COLORS.length], flexShrink: 0 }} />
            <span style={{ fontSize: 12, color: "#334155", flex: 1 }}>{d.label}</span>
            <span style={{ fontSize: 12, fontWeight: 700, color: "#0f172a" }}>{fmt(d.value)}</span>
          </div>
        ))}
      </div>
    </div>
  );
};

const LineChart = ({ data, color = "#7c3aed" }) => {
  if (!data || data.length === 0) return <div style={{ textAlign: "center", color: "#94a3b8", padding: 16 }}>No data</div>;
  const vals = data.map((d) => d.value);
  const min = Math.min(...vals, 0);
  const max = Math.max(...vals, 1);
  const range = max - min || 1;
  const w = 320, h = 100, pad = 14;
  const pts = data.map((d, i) => {
    const x = pad + (i / Math.max(data.length - 1, 1)) * (w - pad * 2);
    const y = pad + ((max - d.value) / range) * (h - pad * 2);
    return `${x},${y}`;
  });

  return (
    <div style={{ overflowX: "auto" }}>
      <svg width={w} height={h + 30} viewBox={`0 0 ${w} ${h + 30}`} style={{ width: "100%", maxWidth: w }}>
        <polyline points={pts.join(" ")} fill="none" stroke={color} strokeWidth={2.5} strokeLinejoin="round" strokeLinecap="round" />
        {data.map((d, i) => {
          const [x, y] = pts[i].split(",").map(Number);
          return (
            <g key={i}>
              <circle cx={x} cy={y} r={4} fill={color} stroke="#fff" strokeWidth={1.5} />
              <text x={x} y={h + 20} textAnchor="middle" fontSize={10} fill="#64748b" fontWeight={600}>{d.label}</text>
            </g>
          );
        })}
      </svg>
    </div>
  );
};

// ════════════════════════════════════════════════════════════════
// MODALS & STANDALONE FORMS (TOP-LEVEL DECLARED TO PREVENT UNMOUNTING)
