// ── Collection / Donation Form (Apple iOS 18 Design) ─────────
const CollectionForm = ({ initial, flats, collections, activeFestivalId, onSave, onClose }) => {
  const today = getLocalDateStr();
  const isInitExternal = initial?.type === "external" || initial?.blockId === "External";
  const [form, setForm] = useState(
    initial
      ? { ...initial, type: isInitExternal ? "external" : "resident" }
      : {
          type: "resident",
          blockId: "A",
          flatNumber: "",
          residentName: "",
          donorCategory: "",
          amount: "",
          date: today,
          paymentMethod: "UPI",
          status: "paid",
          notes: "",
        }
  );
  const [warn, setWarn] = useState("");
  const [duplicatePrompt, setDuplicatePrompt] = useState(null);

  const set = (k, v) => setForm((f) => ({ ...f, [k]: v }));

  const handleFlatChange = (val) => {
    const cleanNum = val.replace(/\D/g, "");
    set("flatNumber", cleanNum);
    if (cleanNum) {
      const match = flats.find((f) => f.blockId === form.blockId && String(f.flatNumber) === cleanNum);
      if (match && match.residentName) {
        setForm((prev) => ({ ...prev, flatNumber: cleanNum, residentName: match.residentName }));
      }
    }
  };

  const handleBlockChange = (blk) => {
    set("blockId", blk);
    if (form.flatNumber) {
      const match = flats.find((f) => f.blockId === blk && String(f.flatNumber) === form.flatNumber);
      if (match && match.residentName) {
        setForm((prev) => ({ ...prev, blockId: blk, residentName: match.residentName }));
      }
    }
  };

  const executeSave = () => {
    const amt = parseAmount(form.amount);
    if (!amt) {
      setWarn("Please enter a valid amount greater than ₹0.");
      return;
    }

    if (form.type === "external") {
      onSave({
        type: "external",
        blockId: "External",
        flatNumber: "External",
        residentName: form.residentName.trim(),
        donorCategory: form.donorCategory ? form.donorCategory.trim() : "",
        amount: amt,
        date: form.date,
        paymentMethod: form.paymentMethod,
        status: "paid",
        notes: form.notes.trim(),
        flatId: `ext_${Date.now()}`,
      });
    } else {
      const cleanFlat = form.flatNumber.replace(/\D/g, "");
      const cleanResident = form.residentName.trim();
      const match = flats.find((f) => f.blockId === form.blockId && String(f.flatNumber) === cleanFlat);

      onSave({
        type: "resident",
        blockId: form.blockId,
        flatNumber: cleanFlat,
        residentName: cleanResident,
        amount: amt,
        date: form.date,
        paymentMethod: form.paymentMethod,
        status: form.status,
        notes: form.notes.trim(),
        flatId: match?.id || `fl_${form.blockId}_${cleanFlat}`,
      });
    }
  };

  const handleSubmit = () => {
    setWarn("");
    const amt = parseAmount(form.amount);
    if (!amt) {
      setWarn("Amount must be a valid positive number greater than ₹0.");
      return;
    }

    if (form.type === "external") {
      if (!form.residentName.trim()) {
        setWarn("Please enter the Donor / Sponsor Name.");
        return;
      }
      executeSave();
    } else {
      const cleanFlat = form.flatNumber.replace(/\D/g, "");
      if (!cleanFlat) {
        setWarn("Please enter a valid numeric Flat Number (e.g. 206).");
        return;
      }

      const flatExists = flats.some((f) => f.blockId === form.blockId && String(f.flatNumber) === cleanFlat && f.active);
      if (!flatExists) {
        const validRange = form.blockId === "C" ? "101-118, 201-218, 301-318, 401-418, 501-518" : "101-114, 201-214, 301-314, 401-414, 501-514";
        setWarn(`Flat ${cleanFlat} does not exist in Block ${form.blockId}. (Valid units: ${validRange})`);
        return;
      }

      if (!form.residentName.trim()) {
        setWarn("Please enter the Resident Name.");
        return;
      }

      if (!initial && collections) {
        const existing = collections.find(
          (c) =>
            c.festivalId === activeFestivalId &&
            c.blockId === form.blockId &&
            String(c.flatNumber).replace(/\D/g, "") === cleanFlat
        );
        if (existing) {
          setDuplicatePrompt({
            flatNumber: `Block ${form.blockId} - Flat ${cleanFlat}`,
            residentName: existing.residentName || form.residentName,
          });
          return;
        }
      }
      executeSave();
    }
  };

  return (
    <>
      {warn && (
        <div style={{ background: "#fef2f2", border: "1.5px solid #fecaca", color: "#b91c1c", padding: "12px 14px", borderRadius: 14, marginBottom: 16, fontSize: 13, fontWeight: 700, display: "flex", gap: 8, alignItems: "center" }}>
          <span>⚠️</span><span>{warn}</span>
        </div>
      )}

      {/* APPLE SEGMENTED INFLOW TYPE SLIDER */}
      {!initial && (
        <div style={{ display: "flex", background: "#f1f5f9", borderRadius: 14, padding: 4, marginBottom: 18, border: "1px solid #e2e8f0" }}>
          <button
            type="button"
            onClick={() => { set("type", "resident"); setWarn(""); }}
            style={{
              flex: 1,
              padding: "10px",
              borderRadius: 11,
              border: "none",
              background: form.type === "resident" ? "#ffffff" : "transparent",
              color: form.type === "resident" ? "#92400e" : "#64748b",
              fontWeight: 800,
              fontSize: 13,
              cursor: "pointer",
              boxShadow: form.type === "resident" ? "0 3px 10px rgba(0,0,0,0.08)" : "none",
              transition: "all 0.15s ease",
            }}
          >
            🏢 Resident Flat
          </button>
          <button
            type="button"
            onClick={() => { set("type", "external"); setWarn(""); }}
            style={{
              flex: 1,
              padding: "10px",
              borderRadius: 11,
              border: "none",
              background: form.type === "external" ? "#ffffff" : "transparent",
              color: form.type === "external" ? "#92400e" : "#64748b",
              fontWeight: 800,
              fontSize: 13,
              cursor: "pointer",
              boxShadow: form.type === "external" ? "0 3px 10px rgba(0,0,0,0.08)" : "none",
              transition: "all 0.15s ease",
            }}
          >
            🌟 External / Sponsor
          </button>
        </div>
      )}

      {duplicatePrompt ? (
        <div style={{ background: "#fffbeb", border: "1.5px solid #fcd34d", borderRadius: 18, padding: 18, marginBottom: 18, textAlign: "center" }}>
          <span style={{ fontSize: 28 }}>⚠️</span>
          <h4 style={{ margin: "8px 0 4px", color: "#92400e", fontSize: 15, fontWeight: 900 }}>Existing Payment Found</h4>
          <p style={{ margin: "0 0 16px", fontSize: 13, color: "#78350f" }}>
            <strong>{duplicatePrompt.flatNumber}</strong> ({duplicatePrompt.residentName}) already contributed. Would you like to record an additional payment?
          </p>
          <div style={{ display: "flex", gap: 10 }}>
            <Btn variant="secondary" onClick={() => setDuplicatePrompt(null)} style={{ flex: 1, borderRadius: 12 }}>Cancel</Btn>
            <Btn onClick={executeSave} style={{ flex: 1, borderRadius: 12 }}>Yes, Add Payment</Btn>
          </div>
        </div>
      ) : (
        <>
          {/* APPLE CASH HERO AMOUNT INPUT CARD */}
          <div
            style={{
              background: "linear-gradient(135deg, #ecfdf5, #d1fae5)",
              border: "1.5px solid #86efac",
              borderRadius: 20,
              padding: "18px 20px",
              marginBottom: 18,
              textAlign: "center",
            }}
          >
            <div style={{ fontSize: 12, fontWeight: 800, color: "#166534", textTransform: "uppercase", letterSpacing: 0.6, marginBottom: 6 }}>
              {form.type === "external" ? "Donation Amount" : "Contribution Amount"}
            </div>
            <div style={{ display: "flex", alignItems: "center", justifyContent: "center", gap: 6 }}>
              <span style={{ fontSize: 26, fontWeight: 900, color: "#15803d" }}>₹</span>
              <input
                type="number"
                min="1"
                placeholder="1000"
                value={form.amount}
                onChange={(e) => set("amount", e.target.value)}
                onWheel={(e) => e.target.blur()}
                style={{
                  fontSize: 32,
                  fontWeight: 900,
                  color: "#15803d",
                  border: "none",
                  background: "transparent",
                  outline: "none",
                  width: "180px",
                  textAlign: "center",
                }}
              />
            </div>

            {/* QUICK PRESET CHIPS */}
            <div style={{ display: "flex", justifyContent: "center", gap: 6, flexWrap: "wrap", marginTop: 12 }}>
              {[500, 1000, 2000, 5000, 10000].map((preset) => (
                <button
                  key={preset}
                  type="button"
                  onClick={() => set("amount", preset)}
                  style={{
                    background: "#ffffff",
                    border: "1px solid #a7f3d0",
                    borderRadius: 10,
                    padding: "4px 10px",
                    fontSize: 12,
                    fontWeight: 800,
                    color: "#166534",
                    cursor: "pointer",
                    boxShadow: "0 2px 5px rgba(22,101,52,0.08)",
                  }}
                >
                  +{preset >= 1000 ? `${preset / 1000}k` : preset}
                </button>
              ))}
            </div>
          </div>

          {/* IOS GROUPED INSET FORM FIELDS */}
          <div style={{ background: "#f8fafc", borderRadius: 20, padding: 18, border: "1.5px solid #e2e8f0", marginBottom: 18 }}>
            {form.type === "resident" ? (
              <>
                {/* Block Selector Chips */}
                <div style={{ marginBottom: 14 }}>
                  <label style={{ display: "block", fontSize: 12, fontWeight: 800, color: "#334155", marginBottom: 6 }}>Select Block *</label>
                  <div style={{ display: "flex", gap: 8 }}>
                    {BLOCKS.map((b) => (
                      <button
                        key={b}
                        type="button"
                        onClick={() => handleBlockChange(b)}
                        style={{
                          flex: 1,
                          padding: "10px",
                          borderRadius: 12,
                          border: form.blockId === b ? "2px solid #f59e0b" : "1.5px solid #cbd5e1",
                          background: form.blockId === b ? "#fef3c7" : "#ffffff",
                          color: form.blockId === b ? "#92400e" : "#475569",
                          fontWeight: 900,
                          fontSize: 14,
                          cursor: "pointer",
                        }}
                      >
                        Block {b}
                      </button>
                    ))}
                  </div>
                </div>

                <div style={{ display: "grid", gridTemplateColumns: "1fr 2fr", gap: 10, marginBottom: 14 }}>
                  <div>
                    <label style={{ display: "block", fontSize: 12, fontWeight: 800, color: "#334155", marginBottom: 6 }}>Flat No. *</label>
                    <Input
                      placeholder="e.g. 206"
                      value={form.flatNumber}
                      onChange={(e) => handleFlatChange(e.target.value)}
                      maxLength={4}
                      style={{ fontSize: 15, fontWeight: 800, textAlign: "center" }}
                    />
                  </div>
                  <div>
                    <label style={{ display: "block", fontSize: 12, fontWeight: 800, color: "#334155", marginBottom: 6 }}>Resident Name *</label>
                    <Input
                      placeholder="e.g. Ramesh Kumar"
                      value={form.residentName}
                      onChange={(e) => set("residentName", e.target.value)}
                    />
                  </div>
                </div>
              </>
            ) : (
              /* EXTERNAL DONOR FIELDS */
              <>
                <div style={{ marginBottom: 14 }}>
                  <label style={{ display: "block", fontSize: 12, fontWeight: 800, color: "#334155", marginBottom: 6 }}>Donor / Sponsor Name *</label>
                  <Input
                    placeholder="e.g. Sri Sai Supermarket, Rajesh Sharma (Guest)"
                    value={form.residentName}
                    onChange={(e) => set("residentName", e.target.value)}
                  />
                </div>

                <div style={{ marginBottom: 14 }}>
                  <label style={{ display: "block", fontSize: 12, fontWeight: 800, color: "#334155", marginBottom: 6 }}>Donor Category / Tag (Optional)</label>
                  <Input
                    placeholder="e.g. Annadanam Donor, Things, Items"
                    value={form.donorCategory}
                    onChange={(e) => set("donorCategory", e.target.value)}
                  />
                </div>
              </>
            )}

            {/* Date & Payment Method */}
            <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 10, marginBottom: 14 }}>
              <div>
                <label style={{ display: "block", fontSize: 12, fontWeight: 800, color: "#334155", marginBottom: 6 }}>Date *</label>
                <Input type="date" value={form.date} onChange={(e) => set("date", e.target.value)} />
              </div>
              <div>
                <label style={{ display: "block", fontSize: 12, fontWeight: 800, color: "#334155", marginBottom: 6 }}>Payment Mode</label>
                <Select value={form.paymentMethod} onChange={(e) => set("paymentMethod", e.target.value)}>
                  {["UPI", "Cash", "Bank Transfer", "Cheque", "Other"].map((m) => <option key={m}>{m}</option>)}
                </Select>
              </div>
            </div>

            {form.type === "resident" && (
              <div style={{ marginBottom: 14 }}>
                <label style={{ display: "block", fontSize: 12, fontWeight: 800, color: "#334155", marginBottom: 6 }}>Status</label>
                <div style={{ display: "flex", gap: 8 }}>
                  {[{ id: "paid", label: "✓ Paid (Full)" }, { id: "partial", label: "⏳ Partial" }].map((st) => (
                    <button
                      key={st.id}
                      type="button"
                      onClick={() => set("status", st.id)}
                      style={{
                        flex: 1,
                        padding: "8px",
                        borderRadius: 10,
                        border: form.status === st.id ? "2px solid #10b981" : "1.5px solid #cbd5e1",
                        background: form.status === st.id ? "#ecfdf5" : "#ffffff",
                        color: form.status === st.id ? "#15803d" : "#475569",
                        fontWeight: 800,
                        fontSize: 13,
                        cursor: "pointer",
                      }}
                    >
                      {st.label}
                    </button>
                  ))}
                </div>
              </div>
            )}

            <div>
              <label style={{ display: "block", fontSize: 12, fontWeight: 800, color: "#334155", marginBottom: 6 }}>Notes / Purpose (Optional)</label>
              <Input
                placeholder="e.g. Day 2 Mandap Flowers / Remaining ₹500 pending"
                value={form.notes}
                onChange={(e) => set("notes", e.target.value)}
              />
            </div>
          </div>

          {/* APPLE EMERALD ACTION BUTTON */}
          <button
            type="button"
            onClick={handleSubmit}
            style={{
              width: "100%",
              height: 52,
              background: "linear-gradient(135deg, #15803d, #16a34a)",
              color: "#ffffff",
              border: "none",
              borderRadius: 16,
              fontSize: 16,
              fontWeight: 800,
              cursor: "pointer",
              boxShadow: "0 10px 25px -5px rgba(22, 163, 74, 0.4)",
              transition: "transform 0.15s ease",
            }}
          >
            {form.type === "external" ? "Save Donation →" : "Save Contribution →"}
          </button>
        </>
      )}
    </>
  );
};

